            st += amzp_position*float2(-1.,1.)/500.; 



            float2 parallax = amzp_parr*float2(-1.,1.)/100.; 

            float2 scaleVec;
            scaleVec = float2(amzp_scale*amzp_stretch.y,amzp_scale*amzp_stretch.x);
            if((amzp_screenSpace>0.5)) {
                float t = scaleVec.x;
                scaleVec.x = scaleVec.y;
                scaleVec.y = t;
            }
            float2 sampleCoord;

            if( (amzp_singleAxis>0.5) ) {
                if( int(amzp_direction)==0 ) {

                    sampleCoord = float2(0.,st.y - center.y);
                } else if( int(amzp_direction) == 1 ) {

                    sampleCoord = float2(st.x - center.x,0.);
                } else if (int(amzp_direction) == 2 ) {

                    sampleCoord = st - center;
                } else if (int(amzp_direction) == 4 ) {

                    sampleCoord = st - center;
                } else if (int(amzp_direction) == 5 ) {

                    sampleCoord = float2(0.,length(st-center));
                } else {

                    float tt = abs(atan(st.x-center.x,st.y-center.y)/6.28318)*2.;
                    sampleCoord = float2(tt,0.);
                }
            } else {
                sampleCoord = st - center;
            }

            float p = turbulence((sampleCoord-0.5)/scaleVec+0.5, int(amzp_octaves), parallax, amzp_evolution + 7391.935*amzp_seed);

            p += (amzp_offs-0.25);
            p *= amzp_intensity * 2.0;

            float2 uv = (amzp_screenSpace>0.5) ? amzScreenNorm() : amzLayerNorm();
            float2 v = uv;

            if( int(amzp_direction)==0 ) {

                v.x += p;
            } else if( int(amzp_direction) == 1 ) {

                v.y += p;
            } else if (int(amzp_direction) == 2 ) {

                float q = turbulence((sampleCoord)/scaleVec+0.5, int(amzp_octaves), parallax, amzp_evolution + 3937.7249*(amzp_seed+6.3379));

                q += (amzp_offs-0.25);
                q *= amzp_intensity * 2.0;
                v.x += p;
                v.y += q;
            } else if (int(amzp_direction) == 4 ) {

                float q = turbulence((sampleCoord)/scaleVec+0.5, int(amzp_octaves), parallax, amzp_evolution + 3937.7249*(amzp_seed+6.3379));
                q += (amzp_offs-0.25);
                q *= amzp_intensity * 2.0;
                float cq = cos(q);
                float sq = sin(q);
                v += normalize(v-0.5)*p;
                v *= float2x2(cq,sq,-sq,cq);
            } else if (int(amzp_direction) == 5 ) {

                float cq = cos(p);
                float sq = sin(p);
                v *= float2x2(cq,sq,-sq,cq);
            } else {

                v += normalize(v-0.5)*p;
            }
            v -= uv;


            float2 texelSize = 1.0 / screen.zw;
            float speed = length(v / texelSize);
            int nSamples = int(clamp(speed, 1.01, 100.01));
            float4 outColor = amzTexture(0,amzScreenNorm());
            float2 vnorm = normalize(v)*texelSize*speed;
            float2 offsetScale = float2(1., 1.);
            if( screen.zw.y > screen.zw.x ) {
                offsetScale.x *= screen.zw.x / screen.zw.y;
            } else {
                offsetScale.y *= screen.zw.y / screen.zw.x;
            }

            for(int i=1; i<nSamples; i++ ) {
                float2 offset = vnorm * float(i) / float(nSamples - 1);
                offset *= offsetScale;
                float2 sample;
                if( (amzp_screenSpace>0.5) ) {
                    sample = amzScreenNorm();
                } else {
                    sample = amzLayerNorm();
                }
                sample = sample + offset;

                if( !(amzp_screenSpace>0.5) ) {
                    sample = (float4(sample,0.0,1.0) * amzLayerToScreen()).xy;
                }

                outColor += amzTexture(0, sample);
            }
            amzOutput = outColor/float(nSamples);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

